-- J0 offline-only additive state authority. No route, Workflow, auth or AI enablement.
-- Retain 008/009 unchanged; default business gate CLOSED. Never delete unknown responsibility.
PRAGMA foreign_keys=ON;
CREATE TABLE shelf_job_control(scope TEXT PRIMARY KEY CHECK(scope='production'),mode TEXT NOT NULL CHECK(mode IN ('closed','jobs-v1')),generation INTEGER NOT NULL CHECK(typeof(generation)='integer' AND generation>=1),updated_at INTEGER NOT NULL CHECK(typeof(updated_at)='integer' AND updated_at>=0));
INSERT INTO shelf_job_control VALUES('production','closed',1,0);
CREATE TABLE shelf_jobs(
 scope TEXT NOT NULL CHECK(scope='production'),job_id TEXT NOT NULL CHECK(length(job_id)=36 AND substr(job_id,9,1)='-' AND substr(job_id,14,1)='-' AND substr(job_id,19,1)='-' AND substr(job_id,24,1)='-' AND length(replace(job_id,'-',''))=32 AND replace(job_id,'-','') NOT GLOB '*[^0-9a-f]*'),request_id TEXT NOT NULL CHECK(length(request_id)=36 AND substr(request_id,9,1)='-' AND substr(request_id,14,1)='-' AND substr(request_id,19,1)='-' AND substr(request_id,24,1)='-' AND length(replace(request_id,'-',''))=32 AND replace(request_id,'-','') NOT GLOB '*[^0-9a-f]*'),logical_fingerprint TEXT NOT NULL CHECK((length(logical_fingerprint)=64 AND logical_fingerprint NOT GLOB '*[^0-9a-f]*')),
 contract TEXT NOT NULL CHECK(contract='jobs-v1'),operation TEXT NOT NULL CHECK(operation IN ('question','chapter_summary','full_summary')),
 model TEXT NOT NULL CHECK(model='gpt-6-luna'),effort TEXT NOT NULL CHECK(effort='low'),prompt_contract TEXT NOT NULL CHECK(prompt_contract='jobs-prompt-v1'),
 origin TEXT NOT NULL CHECK(length(origin) BETWEEN 1 AND 256),book_id TEXT NOT NULL CHECK(length(book_id)=21 AND book_id LIKE 'book_%'),file_id TEXT NOT NULL CHECK(length(file_id)=21 AND file_id LIKE 'file_%'),version_hash TEXT NOT NULL CHECK((length(version_hash)=64 AND version_hash NOT GLOB '*[^0-9a-f]*')),
 source_snapshot_json TEXT NOT NULL CHECK(json_valid(source_snapshot_json) AND length(CAST(source_snapshot_json AS BLOB))<=65536),
 input_json TEXT NOT NULL CHECK(json_valid(input_json) AND length(CAST(input_json AS BLOB))<=32768),input_sha256 TEXT NOT NULL CHECK((length(input_sha256)=64 AND input_sha256 NOT GLOB '*[^0-9a-f]*')),session_hash TEXT NOT NULL CHECK((length(session_hash)=64 AND session_hash NOT GLOB '*[^0-9a-f]*')),
 generation INTEGER NOT NULL CHECK(typeof(generation)='integer' AND generation>=1),gate_generation INTEGER NOT NULL CHECK(typeof(gate_generation)='integer' AND gate_generation>=1),created_at INTEGER NOT NULL CHECK(typeof(created_at)='integer' AND created_at>=1),deadline_at INTEGER NOT NULL CHECK(typeof(deadline_at)='integer' AND deadline_at>=1),billing_day INTEGER NOT NULL CHECK(typeof(billing_day)='integer' AND billing_day>=0),
 max_calls INTEGER NOT NULL CHECK(typeof(max_calls)='integer' AND max_calls>=1),required_calls INTEGER CHECK(required_calls IS NULL OR (typeof(required_calls)='integer' AND required_calls IN (1,3,4))),
 state TEXT NOT NULL CHECK(state IN ('queued','planning','ready','running','cancellation_requested','completed','failed','cancelled','uncertain','orchestration_unknown')),
 version INTEGER NOT NULL CHECK(typeof(version)='integer' AND version>=0),cancel_requested INTEGER NOT NULL CHECK(cancel_requested IN (0,1)),updated_at INTEGER NOT NULL CHECK(typeof(updated_at)='integer' AND updated_at>=1),last_event_id TEXT,
 PRIMARY KEY(scope,job_id),UNIQUE(scope,request_id),UNIQUE(scope,logical_fingerprint),
 FOREIGN KEY(scope,book_id) REFERENCES catalog_books(scope,book_id),FOREIGN KEY(scope,session_hash) REFERENCES sessions(scope,session_hash),
 CHECK(billing_day=created_at/86400000 AND deadline_at<=(billing_day+1)*86400000 AND deadline_at>=created_at+max_calls*960000+(max_calls+1)*30000),
 CHECK((operation='question' AND max_calls=1) OR (operation<>'question' AND max_calls=4)),CHECK(updated_at>=created_at)
);
CREATE UNIQUE INDEX shelf_job_one_active ON shelf_jobs(scope) WHERE state IN ('queued','planning','ready','running','cancellation_requested');
CREATE INDEX shelf_job_history ON shelf_jobs(scope,book_id,created_at,job_id);
CREATE TABLE shelf_job_events(
 scope TEXT NOT NULL,job_id TEXT NOT NULL,event_id TEXT NOT NULL CHECK(length(event_id)=36 AND substr(event_id,9,1)='-' AND substr(event_id,14,1)='-' AND substr(event_id,19,1)='-' AND substr(event_id,24,1)='-' AND length(replace(event_id,'-',''))=32 AND replace(event_id,'-','') NOT GLOB '*[^0-9a-f]*'),kind TEXT NOT NULL CHECK(kind IN ('planning','ready','call_admitted','call_finished','cancel','workflow_observed','stop')),
 expected_version INTEGER NOT NULL CHECK(typeof(expected_version)='integer' AND expected_version>=0),new_version INTEGER NOT NULL CHECK(typeof(new_version)='integer' AND new_version>=1),from_state TEXT NOT NULL,to_state TEXT NOT NULL,cancel_requested INTEGER NOT NULL CHECK(cancel_requested IN (0,1)),
 required_calls INTEGER CHECK(required_calls IS NULL OR (typeof(required_calls)='integer' AND required_calls IN (1,3,4))),created_at INTEGER NOT NULL CHECK(typeof(created_at)='integer' AND created_at>=1),reference_nonce TEXT CHECK(reference_nonce IS NULL OR (length(reference_nonce)=64 AND reference_nonce NOT GLOB '*[^0-9a-f]*')),
 code TEXT NOT NULL CHECK(code IN ('planning','planned','dispatched','completed','upstream_failed','upstream_uncertain','workflow_created','workflow_uncertain','cancelled','local_invalid','source_changed','grant_invalid','deadline')),
 PRIMARY KEY(scope,job_id,event_id),UNIQUE(scope,job_id,new_version),UNIQUE(scope,job_id,kind,reference_nonce),
 FOREIGN KEY(scope,job_id) REFERENCES shelf_jobs(scope,job_id),CHECK(new_version=expected_version+1)
);
CREATE TABLE shelf_job_budget_units(scope TEXT NOT NULL,job_id TEXT NOT NULL,unit_no INTEGER NOT NULL CHECK(typeof(unit_no)='integer' AND unit_no>=1),billing_day INTEGER NOT NULL CHECK(typeof(billing_day)='integer' AND billing_day>=0),created_at INTEGER NOT NULL CHECK(typeof(created_at)='integer' AND created_at>=1),PRIMARY KEY(scope,job_id,unit_no),FOREIGN KEY(scope,job_id) REFERENCES shelf_jobs(scope,job_id),CHECK(unit_no<=4));
CREATE TABLE shelf_job_budget_releases(scope TEXT NOT NULL,job_id TEXT NOT NULL,unit_no INTEGER NOT NULL CHECK(typeof(unit_no)='integer' AND unit_no>=1),event_id TEXT NOT NULL,reason TEXT NOT NULL CHECK(reason IN ('plan_unused','job_terminal')),created_at INTEGER NOT NULL CHECK(typeof(created_at)='integer' AND created_at>=1),PRIMARY KEY(scope,job_id,unit_no),FOREIGN KEY(scope,job_id,unit_no) REFERENCES shelf_job_budget_units(scope,job_id,unit_no),FOREIGN KEY(scope,job_id,event_id) REFERENCES shelf_job_events(scope,job_id,event_id));
CREATE TABLE shelf_job_workflow_intents(scope TEXT NOT NULL,job_id TEXT NOT NULL,instance_id TEXT NOT NULL UNIQUE,claim_nonce TEXT NOT NULL CHECK((length(claim_nonce)=64 AND claim_nonce NOT GLOB '*[^0-9a-f]*')),created_at INTEGER NOT NULL CHECK(typeof(created_at)='integer' AND created_at>=1),expected_version INTEGER NOT NULL CHECK(expected_version=0),PRIMARY KEY(scope,job_id),UNIQUE(claim_nonce),UNIQUE(scope,job_id,claim_nonce),FOREIGN KEY(scope,job_id) REFERENCES shelf_jobs(scope,job_id));
CREATE TABLE shelf_job_workflow_receipts(scope TEXT NOT NULL,job_id TEXT NOT NULL,claim_nonce TEXT NOT NULL CHECK((length(claim_nonce)=64 AND claim_nonce NOT GLOB '*[^0-9a-f]*')),observed_at INTEGER NOT NULL CHECK(typeof(observed_at)='integer' AND observed_at>=1),outcome TEXT NOT NULL CHECK(outcome IN ('created','uncertain')),code TEXT NOT NULL CHECK((outcome='created' AND code='workflow_created') OR (outcome='uncertain' AND code='workflow_uncertain')),PRIMARY KEY(scope,job_id),FOREIGN KEY(scope,job_id,claim_nonce) REFERENCES shelf_job_workflow_intents(scope,job_id,claim_nonce));
CREATE TABLE shelf_job_call_plans(scope TEXT NOT NULL,job_id TEXT NOT NULL,ordinal INTEGER NOT NULL CHECK(typeof(ordinal)='integer' AND ordinal>=1),phase TEXT NOT NULL CHECK(phase IN ('question','leaf','reduce')),input_sha256 TEXT NOT NULL CHECK((length(input_sha256)=64 AND input_sha256 NOT GLOB '*[^0-9a-f]*')),input_codepoints INTEGER NOT NULL CHECK(typeof(input_codepoints)='integer' AND input_codepoints>=1),request_bytes INTEGER NOT NULL CHECK(typeof(request_bytes)='integer' AND request_bytes>=1),coverage_json TEXT NOT NULL CHECK(json_valid(coverage_json) AND json_type(coverage_json)='array' AND length(CAST(coverage_json AS BLOB))<=16384 AND json_array_length(coverage_json)<=256),created_at INTEGER NOT NULL CHECK(typeof(created_at)='integer' AND created_at>=1),PRIMARY KEY(scope,job_id,ordinal),FOREIGN KEY(scope,job_id,ordinal) REFERENCES shelf_job_budget_units(scope,job_id,unit_no),CHECK(ordinal<=4 AND input_codepoints<=50000 AND request_bytes<=262144));
CREATE TABLE shelf_job_call_intents(scope TEXT NOT NULL,job_id TEXT NOT NULL,ordinal INTEGER NOT NULL CHECK(typeof(ordinal)='integer' AND ordinal>=1),dispatch_nonce TEXT NOT NULL CHECK((length(dispatch_nonce)=64 AND dispatch_nonce NOT GLOB '*[^0-9a-f]*')),expected_version INTEGER NOT NULL CHECK(typeof(expected_version)='integer' AND expected_version>=0),billing_day INTEGER NOT NULL CHECK(typeof(billing_day)='integer' AND billing_day>=0),created_at INTEGER NOT NULL CHECK(typeof(created_at)='integer' AND created_at>=1),deadline_at INTEGER NOT NULL CHECK(typeof(deadline_at)='integer' AND deadline_at>=1),body_sha256 TEXT NOT NULL CHECK((length(body_sha256)=64 AND body_sha256 NOT GLOB '*[^0-9a-f]*')),PRIMARY KEY(scope,job_id,ordinal),UNIQUE(dispatch_nonce),UNIQUE(scope,job_id,ordinal,dispatch_nonce),FOREIGN KEY(scope,job_id,ordinal) REFERENCES shelf_job_call_plans(scope,job_id,ordinal),CHECK(created_at/86400000=billing_day AND deadline_at=created_at+900000));
CREATE TABLE shelf_job_call_receipts(
 scope TEXT NOT NULL,job_id TEXT NOT NULL,ordinal INTEGER NOT NULL CHECK(typeof(ordinal)='integer' AND ordinal>=1),dispatch_nonce TEXT NOT NULL CHECK((length(dispatch_nonce)=64 AND dispatch_nonce NOT GLOB '*[^0-9a-f]*')),observed_at INTEGER NOT NULL CHECK(typeof(observed_at)='integer' AND observed_at>=1),outcome TEXT NOT NULL CHECK(outcome IN ('completed','failed','uncertain')),transport_closed INTEGER NOT NULL CHECK(transport_closed=1),usable INTEGER NOT NULL CHECK(usable IN (0,1)),
 code TEXT NOT NULL CHECK((outcome='completed' AND code='completed') OR (outcome='failed' AND code='upstream_failed') OR (outcome='uncertain' AND code='upstream_uncertain')),
 content_text TEXT CHECK(content_text IS NULL OR (length(content_text) BETWEEN 1 AND 16000 AND length(CAST(content_text AS BLOB))<=131072)),content_sha256 TEXT CHECK(content_sha256 IS NULL OR (length(content_sha256)=64 AND content_sha256 NOT GLOB '*[^0-9a-f]*')),
 usage_json TEXT CHECK(usage_json IS NULL OR (json_valid(usage_json) AND json_type(usage_json)='object' AND length(CAST(usage_json AS BLOB))<=1024)),
 coverage_json TEXT NOT NULL CHECK(json_valid(coverage_json) AND json_type(coverage_json)='array' AND length(CAST(coverage_json AS BLOB))<=16384 AND json_array_length(coverage_json)<=256),
 PRIMARY KEY(scope,job_id,ordinal),FOREIGN KEY(scope,job_id,ordinal,dispatch_nonce) REFERENCES shelf_job_call_intents(scope,job_id,ordinal,dispatch_nonce),
 CHECK((outcome='completed' AND content_text IS NOT NULL AND content_sha256 IS NOT NULL) OR (outcome<>'completed' AND content_text IS NULL AND content_sha256 IS NULL AND usable=0))
);
CREATE VIEW shelf_job_current_sources AS SELECT i.scope,i.book_id,i.file_id,i.version_hash,
 json_object('scope',i.scope,'file_id',i.file_id,'version_hash',i.version_hash,'book_id',i.book_id,'text_reservation_id',i.text_reservation_id,'text_logical_key',i.text_logical_key,'package_sha256',i.package_sha256,'source_sha256',i.source_sha256,'etag',i.etag,'format',i.format,'chunk_count',i.chunk_count,'text_bytes',i.text_bytes,'codepoint_count',i.codepoint_count,'index_sha256',i.index_sha256,'created_at',i.created_at,'descriptor_json',i.descriptor_json,'identity_json',i.identity_json,'management_version',i.management_version,'original_descriptor_json',i.original_descriptor_json,'original_etag',i.original_etag,'original_object_key',i.original_object_key,'original_sha256',i.original_sha256,'original_size_bytes',i.original_size_bytes,'original_format',i.original_format,'original_version',i.original_version,'original_catalog_json',i.original_catalog_json,'actual_chunk_count',(SELECT count(*) FROM shelf_prepared_index_chunks c WHERE c.scope=i.scope AND c.file_id=i.file_id AND c.version_hash=i.version_hash),'metadata_version',COALESCE(m.version,0),'metadata_patch_json',COALESCE(m.patch_json,'{}')) AS snapshot_json
 FROM shelf_prepared_readable_sources i LEFT JOIN metadata_overrides m ON m.scope=i.scope AND m.book_id=i.book_id
 WHERE i.chunk_count=(SELECT count(*) FROM shelf_prepared_index_chunks c WHERE c.scope=i.scope AND c.file_id=i.file_id AND c.version_hash=i.version_hash);
CREATE VIEW shelf_ai_charges AS SELECT scope,billing_day,'filename' AS kind,request_id AS owner_id,1 AS unit_no FROM filename_identifications
 UNION ALL SELECT u.scope,u.billing_day,'job',u.job_id,u.unit_no FROM shelf_job_budget_units u WHERE NOT EXISTS(SELECT 1 FROM shelf_job_budget_releases r WHERE r.scope=u.scope AND r.job_id=u.job_id AND r.unit_no=u.unit_no);
CREATE VIEW shelf_ai_slots AS SELECT scope,'filename' AS kind,request_id AS owner_id FROM filename_identifications WHERE state='pending'
 UNION ALL SELECT scope,'job',job_id FROM shelf_jobs WHERE state IN ('queued','planning','ready','running','cancellation_requested')
 UNION ALL SELECT i.scope,'call',i.job_id FROM shelf_job_call_intents i WHERE NOT EXISTS(SELECT 1 FROM shelf_job_call_receipts r WHERE r.scope=i.scope AND r.job_id=i.job_id AND r.ordinal=i.ordinal);
CREATE TRIGGER shelf_job_control_transition BEFORE UPDATE ON shelf_job_control BEGIN
 SELECT CASE WHEN NEW.scope IS NOT OLD.scope OR NEW.generation<>OLD.generation+1 OR NEW.updated_at<OLD.updated_at THEN RAISE(ABORT,'jobs_control_invalid') END;
END;
CREATE TRIGGER shelf_job_control_retain BEFORE DELETE ON shelf_job_control BEGIN SELECT RAISE(ABORT,'jobs_retained'); END;
CREATE TRIGGER shelf_job_header_admit BEFORE INSERT ON shelf_jobs BEGIN
 SELECT CASE WHEN NEW.state<>'queued' OR NEW.version<>0 OR NEW.cancel_requested<>0 OR NEW.required_calls IS NOT NULL OR NEW.last_event_id IS NOT NULL OR NEW.updated_at<>NEW.created_at THEN RAISE(ABORT,'jobs_initial_state') END;
 SELECT CASE WHEN NOT (EXISTS(SELECT 1 FROM sessions s JOIN auth_config a ON a.scope=s.scope JOIN shelf_job_control c ON c.scope=s.scope WHERE s.scope=NEW.scope AND s.session_hash=NEW.session_hash AND s.generation=NEW.generation AND s.revoked=0 AND s.expires_at>NEW.created_at AND a.enabled=1 AND a.generation=s.generation AND a.origin=NEW.origin AND c.mode='jobs-v1' AND c.generation=NEW.gate_generation AND NEW.deadline_at>NEW.created_at)
 AND EXISTS(SELECT 1 FROM shelf_job_current_sources x WHERE x.scope=NEW.scope AND x.book_id=NEW.book_id AND x.file_id=NEW.file_id AND x.version_hash=NEW.version_hash AND x.snapshot_json=NEW.source_snapshot_json)) OR NOT EXISTS(SELECT 1 FROM sessions s WHERE s.scope=NEW.scope AND s.session_hash=NEW.session_hash AND s.expires_at>=NEW.deadline_at) THEN RAISE(ABORT,'jobs_grant_invalid') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM shelf_ai_slots WHERE scope=NEW.scope) THEN RAISE(ABORT,'jobs_busy') END;
 SELECT CASE WHEN (SELECT count(*) FROM shelf_ai_charges WHERE scope=NEW.scope AND billing_day=NEW.billing_day)+NEW.max_calls>20 THEN RAISE(ABORT,'jobs_daily_budget') END;
END;
CREATE TRIGGER shelf_job_header_units AFTER INSERT ON shelf_jobs BEGIN
 INSERT INTO shelf_job_budget_units SELECT NEW.scope,NEW.job_id,n,NEW.billing_day,NEW.created_at FROM (SELECT 1 AS n UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4) WHERE n<=NEW.max_calls;
END;
CREATE TRIGGER shelf_job_header_update BEFORE UPDATE ON shelf_jobs BEGIN
 SELECT CASE WHEN NEW.scope IS NOT OLD.scope OR NEW.job_id IS NOT OLD.job_id OR NEW.request_id IS NOT OLD.request_id OR NEW.logical_fingerprint IS NOT OLD.logical_fingerprint OR NEW.contract IS NOT OLD.contract OR NEW.operation IS NOT OLD.operation OR NEW.model IS NOT OLD.model OR NEW.effort IS NOT OLD.effort OR NEW.prompt_contract IS NOT OLD.prompt_contract OR NEW.origin IS NOT OLD.origin OR NEW.book_id IS NOT OLD.book_id OR NEW.file_id IS NOT OLD.file_id OR NEW.version_hash IS NOT OLD.version_hash OR NEW.source_snapshot_json IS NOT OLD.source_snapshot_json OR NEW.input_json IS NOT OLD.input_json OR NEW.input_sha256 IS NOT OLD.input_sha256 OR NEW.session_hash IS NOT OLD.session_hash OR NEW.generation IS NOT OLD.generation OR NEW.gate_generation IS NOT OLD.gate_generation OR NEW.created_at IS NOT OLD.created_at OR NEW.deadline_at IS NOT OLD.deadline_at OR NEW.billing_day IS NOT OLD.billing_day OR NEW.max_calls IS NOT OLD.max_calls OR NOT EXISTS(SELECT 1 FROM shelf_job_events e WHERE e.scope=OLD.scope AND e.job_id=OLD.job_id AND e.event_id=NEW.last_event_id AND e.expected_version=OLD.version AND e.new_version=NEW.version AND e.from_state=OLD.state AND e.to_state=NEW.state AND e.cancel_requested=NEW.cancel_requested AND e.required_calls IS NEW.required_calls AND e.created_at=NEW.updated_at) THEN RAISE(ABORT,'jobs_event_required') END;
END;
CREATE TRIGGER shelf_job_header_retain BEFORE DELETE ON shelf_jobs BEGIN SELECT RAISE(ABORT,'jobs_retained'); END;
CREATE TRIGGER shelf_job_unit_admit BEFORE INSERT ON shelf_job_budget_units BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM shelf_jobs j WHERE j.scope=NEW.scope AND j.job_id=NEW.job_id AND j.state='queued' AND j.version=0 AND NEW.unit_no<=j.max_calls AND NEW.billing_day=j.billing_day AND NEW.created_at=j.created_at) THEN RAISE(ABORT,'jobs_unit_invalid') END;
 SELECT CASE WHEN (SELECT count(*) FROM shelf_ai_charges WHERE scope=NEW.scope AND billing_day=NEW.billing_day)>=20 THEN RAISE(ABORT,'jobs_daily_budget') END;
END;
CREATE TRIGGER shelf_job_release_admit BEFORE INSERT ON shelf_job_budget_releases BEGIN
 SELECT CASE WHEN EXISTS(SELECT 1 FROM shelf_job_call_intents i WHERE i.scope=NEW.scope AND i.job_id=NEW.job_id AND i.ordinal=NEW.unit_no) OR NOT EXISTS(SELECT 1 FROM shelf_job_events e JOIN shelf_jobs j ON j.scope=e.scope AND j.job_id=e.job_id WHERE e.scope=NEW.scope AND e.job_id=NEW.job_id AND e.event_id=NEW.event_id AND j.last_event_id=e.event_id AND NEW.created_at=e.created_at AND ((NEW.reason='plan_unused' AND e.kind='ready' AND NEW.unit_no>e.required_calls) OR (NEW.reason='job_terminal' AND e.to_state IN ('completed','failed','cancelled','uncertain','orchestration_unknown')))) THEN RAISE(ABORT,'jobs_release_invalid') END;
END;
CREATE TRIGGER shelf_job_workflow_intent_admit BEFORE INSERT ON shelf_job_workflow_intents BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM shelf_jobs j WHERE j.scope=NEW.scope AND j.job_id=NEW.job_id AND j.state='queued' AND j.version=0 AND NEW.created_at=j.created_at AND NEW.instance_id='shelf-job-'||j.job_id) THEN RAISE(ABORT,'jobs_workflow_invalid') END;
END;
CREATE TRIGGER shelf_job_plan_admit BEFORE INSERT ON shelf_job_call_plans BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM shelf_jobs j WHERE j.scope=NEW.scope AND j.job_id=NEW.job_id AND j.state='planning' AND NEW.ordinal<=j.max_calls AND NEW.created_at>=j.updated_at AND EXISTS(SELECT 1 FROM sessions s JOIN auth_config a ON a.scope=s.scope JOIN shelf_job_control c ON c.scope=s.scope WHERE s.scope=j.scope AND s.session_hash=j.session_hash AND s.generation=j.generation AND s.revoked=0 AND s.expires_at>NEW.created_at AND a.enabled=1 AND a.generation=s.generation AND a.origin=j.origin AND c.mode='jobs-v1' AND c.generation=j.gate_generation AND j.deadline_at>NEW.created_at)
 AND EXISTS(SELECT 1 FROM shelf_job_current_sources x WHERE x.scope=j.scope AND x.book_id=j.book_id AND x.file_id=j.file_id AND x.version_hash=j.version_hash AND x.snapshot_json=j.source_snapshot_json)) OR EXISTS(SELECT 1 FROM shelf_job_call_intents i WHERE i.scope=NEW.scope AND i.job_id=NEW.job_id) OR EXISTS(SELECT 1 FROM shelf_job_budget_releases r WHERE r.scope=NEW.scope AND r.job_id=NEW.job_id AND r.unit_no=NEW.ordinal) THEN RAISE(ABORT,'jobs_plan_invalid') END;
END;
CREATE TRIGGER shelf_job_call_intent_admit BEFORE INSERT ON shelf_job_call_intents BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM shelf_jobs j JOIN shelf_job_workflow_intents w ON w.scope=j.scope AND w.job_id=j.job_id WHERE j.scope=NEW.scope AND j.job_id=NEW.job_id AND j.state='ready' AND j.version=NEW.expected_version AND j.cancel_requested=0 AND NEW.ordinal<=j.required_calls AND NEW.billing_day=j.billing_day AND NEW.created_at>=j.updated_at AND NEW.deadline_at<=j.deadline_at-60000 AND EXISTS(SELECT 1 FROM sessions s JOIN auth_config a ON a.scope=s.scope JOIN shelf_job_control c ON c.scope=s.scope WHERE s.scope=j.scope AND s.session_hash=j.session_hash AND s.generation=j.generation AND s.revoked=0 AND s.expires_at>NEW.created_at AND a.enabled=1 AND a.generation=s.generation AND a.origin=j.origin AND c.mode='jobs-v1' AND c.generation=j.gate_generation AND j.deadline_at>NEW.created_at)
 AND EXISTS(SELECT 1 FROM shelf_job_current_sources x WHERE x.scope=j.scope AND x.book_id=j.book_id AND x.file_id=j.file_id AND x.version_hash=j.version_hash AND x.snapshot_json=j.source_snapshot_json)) THEN RAISE(ABORT,'jobs_call_invalid') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM shelf_job_budget_releases r WHERE r.scope=NEW.scope AND r.job_id=NEW.job_id AND r.unit_no=NEW.ordinal) OR EXISTS(SELECT 1 FROM shelf_ai_slots WHERE scope=NEW.scope AND NOT(kind='job' AND owner_id=NEW.job_id)) THEN RAISE(ABORT,'jobs_busy') END;
 SELECT CASE WHEN (SELECT count(*) FROM shelf_job_call_receipts r WHERE r.scope=NEW.scope AND r.job_id=NEW.job_id AND r.ordinal<NEW.ordinal AND r.outcome='completed' AND r.usable=1)<>NEW.ordinal-1 THEN RAISE(ABORT,'jobs_predecessor_invalid') END;
END;
CREATE TRIGGER shelf_job_call_receipt_admit BEFORE INSERT ON shelf_job_call_receipts BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM shelf_job_call_intents i JOIN shelf_jobs j ON j.scope=i.scope AND j.job_id=i.job_id JOIN shelf_job_events e ON e.scope=i.scope AND e.job_id=i.job_id AND e.kind='call_admitted' AND e.reference_nonce=i.dispatch_nonce AND e.expected_version=i.expected_version WHERE i.scope=NEW.scope AND i.job_id=NEW.job_id AND i.ordinal=NEW.ordinal AND i.dispatch_nonce=NEW.dispatch_nonce AND NEW.observed_at>=i.created_at AND NEW.observed_at>=j.updated_at AND j.state IN ('running','cancellation_requested')) THEN RAISE(ABORT,'jobs_receipt_invalid') END;
 SELECT CASE WHEN NEW.usable=1 AND NOT EXISTS(SELECT 1 FROM shelf_jobs j JOIN shelf_job_call_intents i ON i.scope=j.scope AND i.job_id=j.job_id AND i.ordinal=NEW.ordinal AND i.dispatch_nonce=NEW.dispatch_nonce WHERE j.scope=NEW.scope AND j.job_id=NEW.job_id AND j.cancel_requested=0 AND NEW.outcome='completed' AND i.deadline_at>NEW.observed_at AND EXISTS(SELECT 1 FROM sessions s JOIN auth_config a ON a.scope=s.scope JOIN shelf_job_control c ON c.scope=s.scope WHERE s.scope=j.scope AND s.session_hash=j.session_hash AND s.generation=j.generation AND s.revoked=0 AND s.expires_at>NEW.observed_at AND a.enabled=1 AND a.generation=s.generation AND a.origin=j.origin AND c.mode='jobs-v1' AND c.generation=j.gate_generation AND j.deadline_at>NEW.observed_at)
 AND EXISTS(SELECT 1 FROM shelf_job_current_sources x WHERE x.scope=j.scope AND x.book_id=j.book_id AND x.file_id=j.file_id AND x.version_hash=j.version_hash AND x.snapshot_json=j.source_snapshot_json)) THEN RAISE(ABORT,'jobs_grant_invalid') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM shelf_job_call_plans p WHERE p.scope=NEW.scope AND p.job_id=NEW.job_id AND p.ordinal=NEW.ordinal AND p.phase='leaf' AND length(NEW.content_text)>3000) THEN RAISE(ABORT,'jobs_content_limit') END;
 SELECT CASE WHEN NEW.usage_json IS NOT NULL AND ((SELECT count(*) FROM json_each(NEW.usage_json))<>2 OR json_type(NEW.usage_json,'$.input_tokens') IS NOT 'integer' OR json_type(NEW.usage_json,'$.output_tokens') IS NOT 'integer' OR json_extract(NEW.usage_json,'$.input_tokens') NOT BETWEEN 0 AND 9007199254740991 OR json_extract(NEW.usage_json,'$.output_tokens') NOT BETWEEN 0 AND 9007199254740991) THEN RAISE(ABORT,'jobs_usage_invalid') END;
END;
CREATE TRIGGER shelf_job_workflow_receipt_admit BEFORE INSERT ON shelf_job_workflow_receipts BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM shelf_job_workflow_intents w JOIN shelf_jobs j ON j.scope=w.scope AND j.job_id=w.job_id WHERE w.scope=NEW.scope AND w.job_id=NEW.job_id AND w.claim_nonce=NEW.claim_nonce AND NEW.observed_at>=w.created_at AND NEW.observed_at>=j.updated_at) THEN RAISE(ABORT,'jobs_workflow_invalid') END;
END;
CREATE TRIGGER shelf_job_event_admit BEFORE INSERT ON shelf_job_events BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM shelf_jobs j WHERE j.scope=NEW.scope AND j.job_id=NEW.job_id AND j.version=NEW.expected_version AND j.state=NEW.from_state AND NEW.created_at>=j.updated_at AND NEW.cancel_requested>=j.cancel_requested) THEN RAISE(ABORT,'jobs_cas_conflict') END;
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM shelf_jobs j WHERE j.scope=NEW.scope AND j.job_id=NEW.job_id AND (
 (NEW.kind='planning' AND j.state='queued' AND NEW.to_state='planning' AND NEW.code='planning' AND NEW.reference_nonce IS NULL AND NEW.required_calls IS NULL AND NEW.cancel_requested=0 AND EXISTS(SELECT 1 FROM sessions s JOIN auth_config a ON a.scope=s.scope JOIN shelf_job_control c ON c.scope=s.scope WHERE s.scope=j.scope AND s.session_hash=j.session_hash AND s.generation=j.generation AND s.revoked=0 AND s.expires_at>NEW.created_at AND a.enabled=1 AND a.generation=s.generation AND a.origin=j.origin AND c.mode='jobs-v1' AND c.generation=j.gate_generation AND j.deadline_at>NEW.created_at)
 AND EXISTS(SELECT 1 FROM shelf_job_current_sources x WHERE x.scope=j.scope AND x.book_id=j.book_id AND x.file_id=j.file_id AND x.version_hash=j.version_hash AND x.snapshot_json=j.source_snapshot_json)) OR
 (NEW.kind='ready' AND j.state='planning' AND NEW.to_state='ready' AND NEW.code='planned' AND NEW.reference_nonce IS NULL AND NEW.cancel_requested=0 AND ((j.operation='question' AND NEW.required_calls=1) OR (j.operation<>'question' AND NEW.required_calls IN (1,3,4))) AND (SELECT count(*) FROM shelf_job_call_plans p WHERE p.scope=j.scope AND p.job_id=j.job_id)=NEW.required_calls AND (SELECT min(ordinal) FROM shelf_job_call_plans p WHERE p.scope=j.scope AND p.job_id=j.job_id)=1 AND (SELECT max(ordinal) FROM shelf_job_call_plans p WHERE p.scope=j.scope AND p.job_id=j.job_id)=NEW.required_calls AND NOT EXISTS(SELECT 1 FROM shelf_job_call_plans p WHERE p.scope=j.scope AND p.job_id=j.job_id AND p.phase<>CASE WHEN j.operation='question' THEN 'question' WHEN NEW.required_calls=1 OR p.ordinal<NEW.required_calls THEN 'leaf' ELSE 'reduce' END) AND EXISTS(SELECT 1 FROM sessions s JOIN auth_config a ON a.scope=s.scope JOIN shelf_job_control c ON c.scope=s.scope WHERE s.scope=j.scope AND s.session_hash=j.session_hash AND s.generation=j.generation AND s.revoked=0 AND s.expires_at>NEW.created_at AND a.enabled=1 AND a.generation=s.generation AND a.origin=j.origin AND c.mode='jobs-v1' AND c.generation=j.gate_generation AND j.deadline_at>NEW.created_at)
 AND EXISTS(SELECT 1 FROM shelf_job_current_sources x WHERE x.scope=j.scope AND x.book_id=j.book_id AND x.file_id=j.file_id AND x.version_hash=j.version_hash AND x.snapshot_json=j.source_snapshot_json)) OR
 (NEW.kind='call_admitted' AND j.state='ready' AND NEW.to_state='running' AND NEW.code='dispatched' AND NEW.cancel_requested=0 AND NEW.required_calls IS j.required_calls AND EXISTS(SELECT 1 FROM shelf_job_call_intents i WHERE i.scope=j.scope AND i.job_id=j.job_id AND i.dispatch_nonce=NEW.reference_nonce AND i.expected_version=NEW.expected_version AND i.created_at=NEW.created_at)) OR
 (NEW.kind='call_finished' AND NEW.cancel_requested=j.cancel_requested AND NEW.required_calls IS j.required_calls AND EXISTS(SELECT 1 FROM shelf_job_call_receipts r WHERE r.scope=j.scope AND r.job_id=j.job_id AND r.dispatch_nonce=NEW.reference_nonce AND NEW.created_at=r.observed_at AND NEW.code=r.code AND NEW.to_state=CASE WHEN r.outcome='uncertain' THEN 'uncertain' WHEN j.cancel_requested=1 THEN 'cancelled' WHEN r.outcome='failed' OR r.usable=0 THEN 'failed' WHEN r.ordinal=j.required_calls THEN 'completed' ELSE 'ready' END)) OR
 (NEW.kind='cancel' AND j.state IN ('queued','planning','ready','running','cancellation_requested') AND NEW.to_state=CASE WHEN EXISTS(SELECT 1 FROM shelf_job_call_intents i WHERE i.scope=j.scope AND i.job_id=j.job_id AND NOT EXISTS(SELECT 1 FROM shelf_job_call_receipts r WHERE r.scope=i.scope AND r.job_id=i.job_id AND r.ordinal=i.ordinal)) THEN 'cancellation_requested' ELSE 'cancelled' END AND NEW.cancel_requested=1 AND NEW.required_calls IS j.required_calls AND NEW.reference_nonce IS NULL AND NEW.code='cancelled') OR
 (NEW.kind='stop' AND j.state IN ('queued','planning','ready','running','cancellation_requested') AND NEW.to_state='failed' AND NEW.required_calls IS j.required_calls AND NEW.cancel_requested=j.cancel_requested AND NEW.reference_nonce IS NULL AND NEW.code IN ('local_invalid','source_changed','grant_invalid','deadline') AND NOT EXISTS(SELECT 1 FROM shelf_job_call_intents i WHERE i.scope=j.scope AND i.job_id=j.job_id AND NOT EXISTS(SELECT 1 FROM shelf_job_call_receipts r WHERE r.scope=i.scope AND r.job_id=i.job_id AND r.ordinal=i.ordinal))) OR
 (NEW.kind='workflow_observed' AND NEW.cancel_requested=j.cancel_requested AND NEW.required_calls IS j.required_calls AND EXISTS(SELECT 1 FROM shelf_job_workflow_receipts r WHERE r.scope=j.scope AND r.job_id=j.job_id AND r.claim_nonce=NEW.reference_nonce AND r.observed_at=NEW.created_at AND NEW.code=r.code AND NEW.to_state=CASE WHEN r.outcome='uncertain' AND j.state IN ('queued','planning','ready','running','cancellation_requested') AND NOT EXISTS(SELECT 1 FROM shelf_job_call_intents i WHERE i.scope=j.scope AND i.job_id=j.job_id) THEN 'orchestration_unknown' ELSE j.state END))
 )) THEN RAISE(ABORT,'jobs_event_invalid') END;
END;
CREATE TRIGGER shelf_job_event_apply AFTER INSERT ON shelf_job_events BEGIN
 UPDATE shelf_jobs SET state=NEW.to_state,version=NEW.new_version,cancel_requested=NEW.cancel_requested,required_calls=NEW.required_calls,updated_at=NEW.created_at,last_event_id=NEW.event_id WHERE scope=NEW.scope AND job_id=NEW.job_id;
 INSERT INTO shelf_job_budget_releases SELECT u.scope,u.job_id,u.unit_no,NEW.event_id,CASE WHEN NEW.kind='ready' THEN 'plan_unused' ELSE 'job_terminal' END,NEW.created_at FROM shelf_job_budget_units u WHERE u.scope=NEW.scope AND u.job_id=NEW.job_id AND ((NEW.kind='ready' AND u.unit_no>NEW.required_calls) OR NEW.to_state IN ('completed','failed','cancelled','uncertain','orchestration_unknown')) AND NOT EXISTS(SELECT 1 FROM shelf_job_call_intents i WHERE i.scope=u.scope AND i.job_id=u.job_id AND i.ordinal=u.unit_no) AND NOT EXISTS(SELECT 1 FROM shelf_job_budget_releases r WHERE r.scope=u.scope AND r.job_id=u.job_id AND r.unit_no=u.unit_no);
END;
CREATE TRIGGER shelf_job_call_receipt_apply AFTER INSERT ON shelf_job_call_receipts BEGIN
 INSERT INTO shelf_job_events SELECT j.scope,j.job_id,lower(hex(randomblob(4)))||'-'||lower(hex(randomblob(2)))||'-4'||substr(lower(hex(randomblob(2))),2)||'-8'||substr(lower(hex(randomblob(2))),2)||'-'||lower(hex(randomblob(6))),'call_finished',j.version,j.version+1,j.state,CASE WHEN r.outcome='uncertain' THEN 'uncertain' WHEN j.cancel_requested=1 THEN 'cancelled' WHEN r.outcome='failed' OR r.usable=0 THEN 'failed' WHEN r.ordinal=j.required_calls THEN 'completed' ELSE 'ready' END,j.cancel_requested,j.required_calls,NEW.observed_at,NEW.dispatch_nonce,NEW.code FROM shelf_jobs j JOIN shelf_job_call_receipts r ON r.scope=j.scope AND r.job_id=j.job_id AND r.ordinal=NEW.ordinal WHERE j.scope=NEW.scope AND j.job_id=NEW.job_id;
END;
CREATE TRIGGER shelf_job_workflow_receipt_apply AFTER INSERT ON shelf_job_workflow_receipts BEGIN
 INSERT INTO shelf_job_events SELECT j.scope,j.job_id,lower(hex(randomblob(4)))||'-'||lower(hex(randomblob(2)))||'-4'||substr(lower(hex(randomblob(2))),2)||'-8'||substr(lower(hex(randomblob(2))),2)||'-'||lower(hex(randomblob(6))),'workflow_observed',j.version,j.version+1,j.state,CASE WHEN NEW.outcome='uncertain' AND j.state IN ('queued','planning','ready','running','cancellation_requested') AND NOT EXISTS(SELECT 1 FROM shelf_job_call_intents i WHERE i.scope=j.scope AND i.job_id=j.job_id) THEN 'orchestration_unknown' ELSE j.state END,j.cancel_requested,j.required_calls,NEW.observed_at,NEW.claim_nonce,NEW.code FROM shelf_jobs j WHERE j.scope=NEW.scope AND j.job_id=NEW.job_id;
END;
CREATE TRIGGER filename_identification_shared_admit_v1 BEFORE INSERT ON filename_identifications BEGIN
 SELECT CASE WHEN EXISTS(SELECT 1 FROM shelf_ai_slots WHERE scope=NEW.scope AND kind<>'filename') THEN RAISE(ABORT,'jobs_busy') END;
 SELECT CASE WHEN (SELECT count(*) FROM shelf_ai_charges WHERE scope=NEW.scope AND billing_day=NEW.billing_day)>=20 THEN RAISE(ABORT,'identify_daily_budget') END;
END;
